// --- popen 注入 ---
// 危险
FILE *fp = popen(user_input, "r");  // 直接执行用户输入

// 安全: 使用execvp等函数
pid_t pid = fork();
if (pid == 0) {
    execlp("ping", "ping", "-c", "3", sanitized_input, NULL);
}
```

